/**
 * WR-003 [medium · oddity] Page renders "undefined" as visible text
 * Expected: Missing values are shown as a sensible fallback (e.g. "No reviews yet"), never as raw placeholders
 * Actual (bug): Visible text on /products contains "undefined", e.g. "undefined (0)".
 * Source: components/ProductCard.tsx:14 — Products without reviews have rating undefined, so the template renders 'undefined'
 */
test("WR-003: Page renders \"undefined\" as visible text", async ({ page, context }) => {
  const consoleErrors: string[] = [];
  const serverErrors: string[] = [];
  page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(m.text()); });
  page.on("pageerror", (e) => consoleErrors.push(e.message));
  page.on("response", (r) => { if (r.status() >= 500) serverErrors.push(`${r.status()} ${r.url()}`); });
  let res: Awaited<ReturnType<typeof page.request.fetch>> | undefined;

  await page.setViewportSize({ width: 1280, height: 800 });
  await page.goto("/products");
  await page.waitForLoadState("networkidle", { timeout: 5_000 }).catch(() => {});

  await expect(page.locator("body").first()).not.toContainText("undefined");
});
